    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 180px;
    box-sizing: border-box;
    padding: 4px 8px 6px 8px;
  }
  .cb-daily-head {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.78rem;
    font-weight: 600;
