    border-bottom: 1px solid var(--cc-color-border);
    margin-bottom: 6px;
    gap: 12px;
  }
  .cb-daily-title {
    text-transform: uppercase;
    letter-spacing: 0.03em;
    white-space: nowrap;
    opacity: 0.75;
    color: var(--cc-color-text);
    font-size: 0.76rem;
  }
  .cb-daily-legend {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: 8px 14px;
    user-select: none;
    max-height: 44px;
    overflow-y: auto;
  }
  .cb-legend-item {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 0.76rem;
    font-weight: 500;
    color: var(--cc-color-text);
  }
  .cb-legend-box {
    width: 10px;
    height: 10px;
    border-radius: 2px;
    flex-shrink: 0;
    display: inline-block;
    border: 1px solid var(--cc-color-border);
  }
  .cb-legend-label {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    max-width: 180px;
  }
  .cb-daily-wrap {
    display: flex;
    flex-direction: row;
    align-items: stretch;
    flex: 1;
    min-height: 160px;
    font-family: inherit;
    box-sizing: border-box;
    padding: 0;
    overflow: hidden;
  }
  .cb-daily-main {
    display: flex;
    flex: 1;
    position: relative;
    min-height: 160px;
    gap: 8px;
    min-width: 0;
  }
  .cb-hist-y {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    font-size: 0.72rem;
    color: var(--cc-color-text);
    opacity: 0.72;
    text-align: right;
    padding-right: 8px;
    min-width: 48px;
    white-space: nowrap;
    border-right: 1px solid var(--cc-color-border);
    user-select: none;
    margin-top: 1px;
    margin-bottom: 20px;
    box-sizing: border-box;
    font-variant-numeric: tabular-nums;
  }
